package com.bank.risingthreads;

import org.junit.jupiter.api.Test;
import java.lang.management.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class RisingThreadsTest {

    // ═══ Thread leak: newCachedThreadPool creates unlimited threads ═══
    @Test
    void threadLeak_cachedPool() throws InterruptedException {
        ExecutorService leaky = Executors.newCachedThreadPool();

        for (int i = 0; i < 200; i++) {
            leaky.submit(() -> {
                try { Thread.sleep(5000); } catch (InterruptedException e) {}
            });
        }
        Thread.sleep(200);

        ThreadPoolExecutor tpe = (ThreadPoolExecutor) leaky;
        System.out.println("Thread count: " + tpe.getPoolSize());
        assertThat(tpe.getPoolSize()).isGreaterThanOrEqualTo(100);
        // 200 threads created! In production: 10K+ → OOM!
        leaky.shutdownNow();
    }

    // ═══ FIX: bounded pool caps thread count ═══
    @Test
    void bounded_capsThreads() throws InterruptedException {
        ThreadPoolExecutor bounded = new ThreadPoolExecutor(
            5, 10, 60, TimeUnit.SECONDS,
            new LinkedBlockingQueue<>(100),
            new ThreadPoolExecutor.CallerRunsPolicy()
        );

        for (int i = 0; i < 200; i++) {
            bounded.submit(() -> {
                try { Thread.sleep(200); } catch (InterruptedException e) {}
            });
        }
        Thread.sleep(100);

        assertThat(bounded.getPoolSize()).isLessThanOrEqualTo(10);  // CAPPED!
        System.out.println("Bounded pool: " + bounded.getPoolSize() + " threads");
        bounded.shutdown();
        bounded.awaitTermination(30, TimeUnit.SECONDS);
    }

    // ═══ Monitor thread count programmatically ═══
    @Test
    void monitorThreadCount() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        int count = tmx.getThreadCount();
        int peak = tmx.getPeakThreadCount();
        System.out.println("Current threads: " + count + ", Peak: " + peak);
        // Expose as Prometheus gauge: jvm_threads_current, jvm_threads_peak
        // Alert: thread count > 500 → investigate!
    }

    // ═══ Identify waiting threads ═══
    @Test
    void identifyWaitingThreads() {
        ThreadMXBean tmx = ManagementFactory.getThreadMXBean();
        ThreadInfo[] infos = tmx.dumpAllThreads(false, false);

        long blocked = java.util.Arrays.stream(infos)
            .filter(i -> i.getThreadState() == Thread.State.BLOCKED).count();
        long waiting = java.util.Arrays.stream(infos)
            .filter(i -> i.getThreadState() == Thread.State.WAITING).count();
        long timedWaiting = java.util.Arrays.stream(infos)
            .filter(i -> i.getThreadState() == Thread.State.TIMED_WAITING).count();

        System.out.println("BLOCKED: " + blocked + ", WAITING: " + waiting + ", TIMED_WAITING: " + timedWaiting);
    }
}
